def is_one_edit_away(a, b):
    la, lb = len(a), len(b)
    if abs(la - lb) > 1:
        return False
    if la == lb:
        return sum(1 for x, y in zip(a, b) if x != y) <= 1
    shorter, longer = (a, b) if la < lb else (b, a)
    i = 0
    skipped = False
    for ch in longer:
        if i < len(shorter) and shorter[i] == ch:
            i += 1
        elif not skipped:
            skipped = True
        else:
            return False
    return True

def has_balanced_quotes(s):
    single = 0
    double = 0
    for c in s:
        if c == "'":
            single += 1
        elif c == '"':
            double += 1
    return single % 2 == 0 and double % 2 == 0

