def is_palindrome_in_base(n, base):
    if n == 0:
        digits = [0]
    else:
        digits = []
        x = n
        while x > 0:
            digits.append(x % base)
            x //= base
    return digits == list(reversed(digits))

def largest_number_with_digit_sum(s, d):
    if s < 1 or s > 9 * d:
        return -1
    digits = []
    remaining = s
    for _ in range(d):
        use = min(9, remaining)
        digits.append(use)
        remaining -= use
    return int("".join(str(x) for x in digits))

def is_sum_of_two_squares(n):
    squares = set()
    a = 0
    while a * a <= n:
        squares.add(a * a)
        a += 1
    return any((n - sq) in squares for sq in squares if n - sq >= 0)

def count_perfect_numbers_in_range(a, b):
    def divisor_sum(num):
        if num <= 1:
            return 0
        s = 1
        d = 2
        while d * d <= num:
            if num % d == 0:
                s += d
                other = num // d
                if other != d:
                    s += other
            d += 1
        return s
    cnt = 0
    for val in range(max(a, 1), b + 1):
        if val > 1 and divisor_sum(val) == val:
            cnt += 1
    return cnt

