def compress_to_tuples(s):
    if not s:
        return []
    result = []
    current = s[0]
    n = 1
    for ch in s[1:]:
        if ch == current:
            n += 1
        else:
            result.append((current, n))
            current = ch
            n = 1
    result.append((current, n))
    return result

