def is_valid_variable_declaration(s):
    types = {'int', 'float', 'str', 'bool'}
    tokens = s.split(' ')
    if len(tokens) != 2:
        return False
    t, name = tokens
    if t not in types:
        return False
    if len(name) == 0:
        return False
    if not (name[0].isalpha() or name[0] == '_'):
        return False
    for ch in name[1:]:
        if not (ch.isalnum() or ch == '_'):
            return False
    return True

