def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

from itertools import groupby

def compress_repeated_chars(s):
    parts = []
    for ch, group in groupby(s):
        parts.append(ch + str(len(list(group))))
    return ''.join(parts)

def find_min_sum_subarray_of_size_k(lst, k):
    window_sum = sum(lst[:k])
    min_sum = window_sum
    for i in range(k, len(lst)):
        window_sum += lst[i] - lst[i - k]
        if window_sum < min_sum:
            min_sum = window_sum
    return min_sum

def count_repeating_unit_repeats(s):
    n = len(s)
    if n == 0:
        return 0
    for repeats in range(n, 1, -1):
        if n % repeats == 0:
            unit_len = n // repeats
            unit = s[:unit_len]
            if unit * repeats == s:
                return repeats
    return 1

